def build(i):
    out = {}
    for row in D.strip().split("\n"):
        p = row.split("|")
        out[p[0]] = {"title": p[1 + 2*i], "hook": p[2 + 2*i]}
    assert list(out) == CODES, [c for c in CODES if c not in out]
    return out
